create table `ddl_people` (`id` bigint primary key auto_increment, `name` varchar(255) not null) default character set utf8mb4 collate utf8mb4_0900_bin;
create table `ddl_kinds` (`kind_id` bigint primary key auto_increment, `label` varchar(40) not null, `body` longtext not null, `count` integer not null, `big` bigint not null, `ratio` double not null, `price` numeric(8, 2) not null, `exact` numeric(12, 4) not null, `flag` boolean not null, `meta` json not null, `token` char(36) not null, `blob` longblob not null, `day` date not null, `at` datetime(3) not null) default character set utf8mb4 collate utf8mb4_0900_bin;
create table `ddl_modifiers` (`id` char(36) default (lower(concat(substr(lpad(hex(cast(unix_timestamp(now(3)) * 1000 as unsigned)), 12, '0'), 1, 8), '-', substr(lpad(hex(cast(unix_timestamp(now(3)) * 1000 as unsigned)), 12, '0'), 9, 4), '-7', substr(hex(random_bytes(2)), 2), '-', substr('89ab', 1 + (ord(random_bytes(1)) & 3), 1), substr(hex(random_bytes(2)), 2), '-', hex(random_bytes(6))))) primary key, `email` varchar(255) not null, `nickname` varchar(255), `role` varchar(255) default 'member' not null, `level` integer default 1 not null, `active` boolean default true not null, `settings` json default (cast('{}' as json)) not null, `password` varchar(255) not null, `api_key` varchar(255), `public_id` char(36) default (lower(concat(substr(lpad(hex(cast(unix_timestamp(now(3)) * 1000 as unsigned)), 12, '0'), 1, 8), '-', substr(lpad(hex(cast(unix_timestamp(now(3)) * 1000 as unsigned)), 12, '0'), 9, 4), '-7', substr(hex(random_bytes(2)), 2), '-', substr('89ab', 1 + (ord(random_bytes(1)) & 3), 1), substr(hex(random_bytes(2)), 2), '-', hex(random_bytes(6))))) not null, `seen_at` datetime(3) default (utc_timestamp(3)), `created_at` datetime(3) default (utc_timestamp(3)) not null, `updated_at` datetime(3) default (utc_timestamp(3)) not null, `deleted_at` datetime(3)) default character set utf8mb4 collate utf8mb4_0900_bin;
create unique index `ddl_modifiers_email_unique` on `ddl_modifiers` (`email`);
create unique index `ddl_modifiers_api_key_unique` on `ddl_modifiers` (`api_key`);
create unique index `ddl_modifiers_public_id_unique` on `ddl_modifiers` (`public_id`);
create table `ddl_categories` (`id` bigint primary key auto_increment, `title` varchar(255) not null) default character set utf8mb4 collate utf8mb4_0900_bin;
create table `ddl_codes` (`code` varchar(255) primary key, `title` varchar(255) not null) default character set utf8mb4 collate utf8mb4_0900_bin;
create table `ddl_keys` (`id` bigint primary key auto_increment, `person_id` bigint not null, `editor_id` bigint, `owner_id` bigint not null, `plain_id` bigint not null, `modifier_id` char(36), `loose_id` bigint not null, `ddl_category_id` bigint not null, constraint `ddl_keys_person_id_fkey` foreign key (`person_id`) references `ddl_people` (`id`) on delete cascade, constraint `ddl_keys_editor_id_fkey` foreign key (`editor_id`) references `ddl_people` (`id`) on delete set null, constraint `ddl_keys_owner_id_fkey` foreign key (`owner_id`) references `ddl_people` (`id`) on delete restrict, constraint `ddl_keys_plain_id_fkey` foreign key (`plain_id`) references `ddl_people` (`id`), constraint `ddl_keys_modifier_id_fkey` foreign key (`modifier_id`) references `ddl_modifiers` (`id`) on delete cascade, constraint `ddl_keys_ddl_category_id_fkey` foreign key (`ddl_category_id`) references `ddl_categories` (`id`)) default character set utf8mb4 collate utf8mb4_0900_bin;
